kNeighbours = input(7, "K Neighbours", 1, 15, 1)
FeatureBars = input(20, "Feature Bars", 5, 30, 1)
NeighbourPool = input(200, "Neighbour Pool", 30, 500, 5)
DisagreementThreshold = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.05)
MarginThreshold = input(0.3, "Margin Threshold", 0.05, 1.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Current-window normalization (max abs pct change guard) ───
maxAbsCur = 0.000000001
f = 0
while f < FeatureBars {
    c0 = close[f]
    c1 = close[f + 1]
    pc = 0.0
    if c1 != 0 { pc := (c0 - c1) / c1 }
    a = abs(pc)
    if a > maxAbsCur { maxAbsCur := a }
    f := f + 1
}

// ─── KNN search state (reset every bar) ───
b0 = 999999.0
b1 = 999999.0
b2 = 999999.0
b3 = 999999.0
b4 = 999999.0
b5 = 999999.0
b6 = 999999.0
t0 = 0
t1 = 0
t2 = 0
t3 = 0
t4 = 0
t5 = 0
t6 = 0

warmup = bar_index >= NeighbourPool + FeatureBars + 5

// ─── Euclidean search over last NeighbourPool windows ───
p = 1
while p <= NeighbourPool {
    maxAbsHist = 0.000000001
    fh = 0
    while fh < FeatureBars {
        hc0 = close[p + fh]
        hc1 = close[p + fh + 1]
        hpc = 0.0
        if hc1 != 0 { hpc := (hc0 - hc1) / hc1 }
        ha = abs(hpc)
        if ha > maxAbsHist { maxAbsHist := ha }
        fh := fh + 1
    }
    dist = 0.0
    fd = 0
    while fd < FeatureBars {
        cc0 = close[fd]
        cc1 = close[fd + 1]
        cpc = 0.0
        if cc1 != 0 { cpc := (cc0 - cc1) / cc1 }
        cn = cpc / maxAbsCur
        hh0 = close[p + fd]
        hh1 = close[p + fd + 1]
        hpc2 = 0.0
        if hh1 != 0 { hpc2 := (hh0 - hh1) / hh1 }
        hn = hpc2 / maxAbsHist
        d = cn - hn
        dist := dist + d * d
        fd := fd + 1
    }
    lbl = 0 - 1
    if close[p - 1] > close[p] { lbl := 1 }
    if warmup {
        if dist < b0 {
            b6 := b5
            t6 := t5
            b5 := b4
            t5 := t4
            b4 := b3
            t4 := t3
            b3 := b2
            t3 := t2
            b2 := b1
            t2 := t1
            b1 := b0
            t1 := t0
            b0 := dist
            t0 := lbl
        } else {
            if dist < b1 {
                b6 := b5
                t6 := t5
                b5 := b4
                t5 := t4
                b4 := b3
                t4 := t3
                b3 := b2
                t3 := t2
                b2 := b1
                t2 := t1
                b1 := dist
                t1 := lbl
            } else {
                if dist < b2 {
                    b6 := b5
                    t6 := t5
                    b5 := b4
                    t5 := t4
                    b4 := b3
                    t4 := t3
                    b3 := b2
                    t3 := t2
                    b2 := dist
                    t2 := lbl
                } else {
                    if dist < b3 {
                        b6 := b5
                        t6 := t5
                        b5 := b4
                        t5 := t4
                        b4 := b3
                        t4 := t3
                        b3 := dist
                        t3 := lbl
                    } else {
                        if dist < b4 {
                            b6 := b5
                            t6 := t5
                            b5 := b4
                            t5 := t4
                            b4 := dist
                            t4 := lbl
                        } else {
                            if dist < b5 {
                                b6 := b5
                                t6 := t5
                                b5 := dist
                                t5 := lbl
                            } else {
                                if dist < b6 {
                                    b6 := dist
                                    t6 := lbl
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    p := p + 1
}

// ─── Vote margin + disagreement as two independent channels ───
bullCount = 0
if t0 == 1 { bullCount := bullCount + 1 }
if kNeighbours >= 2 and t1 == 1 { bullCount := bullCount + 1 }
if kNeighbours >= 3 and t2 == 1 { bullCount := bullCount + 1 }
if kNeighbours >= 4 and t3 == 1 { bullCount := bullCount + 1 }
if kNeighbours >= 5 and t4 == 1 { bullCount := bullCount + 1 }
if kNeighbours >= 6 and t5 == 1 { bullCount := bullCount + 1 }
if kNeighbours >= 7 and t6 == 1 { bullCount := bullCount + 1 }
bearCount = kNeighbours - bullCount
voteMargin = 0.0
if warmup { voteMargin := (bullCount - bearCount) / kNeighbours }
disagreement = 1 - abs(voteMargin)
if warmup == false { disagreement := 1.0 }
marginAbs = abs(voteMargin)
crispness = 1 - disagreement

// ─── Signals: both channels must agree (gated on fresh entry) ───
bullNow = voteMargin > MarginThreshold and disagreement < DisagreementThreshold
bearNow = voteMargin < 0 - MarginThreshold and disagreement < DisagreementThreshold
bullPrev = voteMargin[1] > MarginThreshold and disagreement[1] < DisagreementThreshold
bearPrev = voteMargin[1] < 0 - MarginThreshold and disagreement[1] < DisagreementThreshold
buySig = bullNow and bullPrev == false and warmup
sellSig = bearNow and bearPrev == false and warmup

// ─── Cone size proportional to margin crispness ───
coneBase = 0.6 + marginAbs * 1.6
coneSize = coneBase * markerSize
if coneSize > 2.2 { coneSize := 2.2 }
if coneSize < 0.6 { coneSize := 0.6 }

if buySig {
