plot3d(voteMargin * 100, "Vote Margin Blocks", "bars3d", "#22cc88", "separate")
plot3d(disagreement * 100, "Disagreement Cloud", "scatter", "#ff44cc", "separate", 1)

// Visible Value Terrain POC Model
// Volume-profile-at-price engine: POC + value-area expansion rendered as terrain.

Rows = input(24, "Rows", 5, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
extRight = input(5, "Extend Lines Right", 1, 20, 1)
showVA = input(true, "Show Value Area")
use3D = input(true, "Use 3D Mode")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range: visible-session proxy ─────────────────────────
sessLen = 60
sh = highest(high, sessLen)
sl = lowest(low, sessLen)
rng = sh - sl
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / Rows
if rowH <= 0 {
    rowH := close * 0.001
}

// ─── Distribute volume into price rows ────────────────────────────
// ATR: not used (volume-profile only per binding). Row overlap allocation.
rowVol = array()
r = 0
while r < Rows {
    array.push(rowVol, 0.0)
    r := r + 1
}
totalVol = 0.0
j = 0
while j < sessLen {
    if j <= bar_index {
        bHigh = high[j]
        bLow = low[j]
        bVol = volume[j]
        totalVol := totalVol + bVol
        barRng = bHigh - bLow
        if barRng <= 0 {
            cr = floor((bLow - sl) / rng * Rows)
            if cr < 0 { cr := 0 }
            if cr > Rows - 1 { cr := Rows - 1 }
            array.set(rowVol, cr, array.get(rowVol, cr) + bVol)
        } else {
            k = 0
            while k < Rows {
                rowLow = sl + k * rowH
                rowTop = rowLow + rowH
                top = bHigh
                if rowTop < top { top := rowTop }
                bot = bLow
                if rowLow > bot { bot := rowLow }
                ov = top - bot
                if ov > 0 {
                    alloc = bVol * ov / barRng
                    array.set(rowVol, k, array.get(rowVol, k) + alloc)
                }
                k := k + 1
            }
        }
    }
    j := j + 1
}

// ─── Point of control: max-volume row ─────────────────────────────
pocRow = 0
pocVol = array.get(rowVol, 0)
q = 1
while q < Rows {
    v = array.get(rowVol, q)
    if v > pocVol {
        pocVol := v
        pocRow := q
    }
    q := q + 1
}
pocLow = sl + pocRow * rowH
pocPrice = pocLow + rowH * 0.5
pocStrength = 0.0
if totalVol > 0 {
    pocStrength := pocVol / totalVol * 100
}

// ─── Value area: expand from POC ──────────────────────────────────
vaLowRow = pocRow
vaHighRow = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < Rows {
    leftVal = 0 - 1.0
    if vaLowRow > 0 { leftVal := array.get(rowVol, vaLowRow - 1) }
    rightVal = 0 - 1.0
    if vaHighRow < Rows - 1 { rightVal := array.get(rowVol, vaHighRow + 1) }
    if rightVal >= leftVal {
        if vaHighRow < Rows - 1 {
            vaHighRow := vaHighRow + 1
            accum := accum + rightVal
        } else {
            if vaLowRow > 0 {
                vaLowRow := vaLowRow - 1
                accum := accum + leftVal
            } else {
                accum := target
            }
        }
    } else {
        if vaLowRow > 0 {
            vaLowRow := vaLowRow - 1
            accum := accum + leftVal
        } else {
            if vaHighRow < Rows - 1 {
                vaHighRow := vaHighRow + 1
                accum := accum + rightVal
            } else {
                accum := target
            }
        }
    }
    guard := guard + 1
}
VAH = sl + (vaHighRow + 1) * rowH
VAL = sl + vaLowRow * rowH

// ─── Terrain height at current price row ──────────────────────────
closeRow = floor((close - sl) / rng * Rows)
if closeRow < 0 { closeRow := 0 }
if closeRow > Rows - 1 { closeRow := Rows - 1 }
volAtPrice = array.get(rowVol, closeRow)
terrainAtPrice = 0.0
if pocVol > 0 { terrainAtPrice := volAtPrice / pocVol * 100 }
vaShare = 0.0
if totalVol > 0 { vaShare := accum / totalVol * 100 }

// ─── Signal state ─────────────────────────────────────────────────
var wasInside = true
inside = close >= VAL and close <= VAH
insidePrev = close[1] >= VAL and close[1] <= VAL + (VAH - VAL)
buySig = insidePrev and close > VAH
sellSig = insidePrev and close < VAL
retInside = not insidePrev and inside

// breakout strength from volume distribution (no foreign families)
brkVol = volAtPrice
if pocVol > 0 { brkVol := volAtPrice / pocVol }
coneSz = 0.6 + brkVol * 1.2
if coneSz < 0.6 { coneSz := 0.6 }
if coneSz > 2.2 { coneSz := 2.2 }
coneSz := coneSz * markerSize

// ─── Signal markers (2D) + automation ─────────────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", coneSz, "3d")
    model.longEntry("Buy", 1)
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", coneSz, "3d")
    model.shortEntry("Sell", 1)
}
if retInside {
    plotshape(bar_index, close, "Back", "circle", "#ffd43b")
}
wasInside := inside

// ─── POC rail label: only on new POC level (rare) ─────────────────
var wasPocRail = 0.0
if pocPrice != wasPocRail {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}
wasPocRail := pocPrice

// ─── 2D value-zone drawings ───────────────────────────────────────
if showVA {
    box.new(bar_index - sessLen, VAH, bar_index + extRight, VAL, "#22cc88", "rgba(34,204,136,0.08)", 1, "VAZONE")
    line.new(bar_index - sessLen, pocPrice, bar_index + extRight, pocPrice, "#ffd43b", 2, "solid", false, "POCLINE")
    line.new(bar_index - sessLen, VAH, bar_index + extRight, VAH, "#22cc88", 1, "dashed", false, "VAHLINE")
    line.new(bar_index - sessLen, VAL, bar_index + extRight, VAL, "#ff4477", 1, "dashed", false, "VALLINE")
    text.new(bar_index + extRight, pocPrice, "POC", "#ffd43b", 1, "POCTXT")
    text.new(bar_index + extRight, VAH, "VAH", "#22cc88", 1, "VAHTXT")
    text.new(bar_index + extRight, VAL, "VAL", "#ff4477", 1, "VALTXT")
    h = 0
    while h < Rows {
        rl = sl + h * rowH
        rt = rl + rowH
        rv = array.get(rowVol, h)
        norm = 0.0
        if pocVol > 0 { norm := rv / pocVol }
        rr = bar_index + 1 + norm * extRight
        box.new(bar_index + 1, rt, rr, rl, "#888888", "rgba(136,136,136,0.35)", 1)
        h := h + 1
    }
}
if buySig { bgcolor("rgba(34,204,136,0.08)") }
if sellSig { bgcolor("rgba(255,68,119,0.08)") }

// ─── Unconditional rendering (2D twins carry same info) ───────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(VAH, "VAH", "#22cc88", 1, "stepline")
plot(VAL, "VAL", "#ff4477", 1, "stepline")
plot(terrainAtPrice, "Vol At Price", "#888888", 1, "separate")
plot(pocStrength, "POC Strength", "#ffd43b", 1, "separate")

// ─── 3D: terrain surface + labelled POC rail + value rails ────────
plot3d(terrainAtPrice, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(VAH, "VAH Rail", "line3d", "#22cc88", "3d", 2)

